-- Daily challenges for 2026-11-23: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-11-23. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('being-someone-people-can-count-on', 'Being Someone People Can Count On', 'For anyone who wants the people in their life to feel they can rely on them. Each day is one small way to keep your word, show up when you said you would, follow through on little promises, and be honest when you can''t.', 'Relationships', 365, array['Values', 'Relationships']::text[], 1, '2026-11-23T17:00:00+00:00'::timestamptz),
  ('tidying-your-digital-life', 'Tidying Your Digital Life', 'For anyone whose phone, computer and inbox feel as cluttered as a junk drawer. Each day is one small way to clear old files, sort photos, quiet alerts and organize accounts, so your digital life feels lighter and easier to find your way around.', 'Habits', 365, array['Habits', 'Stress']::text[], 1, '2026-11-23T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('being-someone-people-can-count-on', 'tidying-your-digital-life');

